using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// A sample type we'll resolve metadata for.
public record Person(string Name, int Age);

// A type the source generator does NOT know about.
public record Unknown(string Id);

// Source-generated context that only includes Person.
[JsonSerializable(typeof(Person))]
public partial class AppJsonContext : JsonSerializerContext;

var options = new JsonSerializerOptions
{
    TypeInfoResolver = AppJsonContext.Default
};

// 1) Strongly-typed metadata — returns JsonTypeInfo<Person> directly.
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got JsonTypeInfo<Person>  →  Type = {personInfo.Type.Name}");

// Round-trip with the typed info to prove it works.
var json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
var back = JsonSerializer.Deserialize(json, personInfo)!;
Console.WriteLine($"Round-trip: {back}");

// 2) Probe without throwing — TryGetTypeInfo returns false when
//    the resolver doesn't support the requested type.
if (options.TryGetTypeInfo(typeof(Unknown), out JsonTypeInfo? unknownInfo))
{
    Console.WriteLine($"Got metadata for Unknown: {unknownInfo!.Type.Name}");
}
else
{
    Console.WriteLine("No metadata for Unknown — and no exception was thrown.");
}

